#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

using s64 = long long;

int l, r, p;
vector<int> primes;
vector<int> poss;

inline bool isPrime(int num)
{
    for (int prime : primes) {
        if ((s64)prime * prime > num)
            break;
        if (num % prime == 0)
            return false;
    }
    return true;
}

void dfs(int num, size_t v)
{
    if (v == primes.size()) {
        poss.push_back(num);
        return;
    }

    dfs(num, v + 1);
    while ((s64)num * primes[v] <= r) {
        num *= primes[v];
        dfs(num, v + 1);
    }
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> l >> r >> p;

    for (int i = 2; i <= p; ++i)
        if (isPrime(i))
            primes.push_back(i);

    dfs(1, 0);
    sort(poss.begin(), poss.end());

    vector<char> ok(poss.size(), false);
    vector<int> f(poss.size(), INT_MAX);

    f[0] = 0;
    ok[0] = true;

    for (int b = 2; b <= p; ++b) {
        size_t j = 0;
        for (size_t i = 0; i < poss.size(); ++i) {
            if (f[i] == INT_MAX)
                continue;

            if ((s64)f[i] + b <= p)
                ok[i] = true;

            const s64 target = (s64)poss[i] * b;
            while (j < poss.size() && poss[j] < target)
                ++j;

            if (j < poss.size() && poss[j] == target)
                f[j] = min(f[j], f[i] + 1);
        }
    }

    int result = 0;
    for (size_t i = 0; i < poss.size(); ++i)
        if (l <= poss[i] && poss[i] <= r && ok[i])
            ++result;

    cout << result << '\n';
    return 0;
}

