template <class T>
inline void tension(T& a, const T& b)
{
    if (b < a)
        a = b;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int l, r, p;
    cin >> l >> r >> p;

    vector<int> primes;
    for (int num = 2; num <= p; ++num)
