    {
        if (v == primes.size())
        {
            poss.push_back(num);
            return;
        }

        self(self, num, v + 1);
        while ((s64)num * primes[v] <= r)
        {
            num *= primes[v];
            self(self, num, v + 1);
        }
    };

    dfs(dfs, 1, 0);
    sort(poss.begin(), poss.end());

    const int nPoss = static_cast<int>(poss.size());
    vector<unsigned char> ok(nPoss, false);
    vector<int> f(nPoss, INT_MAX);

    f[0] = 0;
    ok[0] = true;

    for (int b = 2; b <= p; ++b)
    {
        int j = 0;
        for (int i = 0; i < nPoss; ++i)
        {
            if (f[i] == INT_MAX)
                continue;

            if (f[i] + b <= p)
                ok[i] = true;

            const s64 target = (s64)poss[i] * b;
            while (j < nPoss && poss[j] < target)
                ++j;

            if (j < nPoss && poss[j] == target)
                tension(f[j], f[i] + 1);
        }
    }

    int result = 0;
    for (int i = 0; i < nPoss; ++i)
        if (l <= poss[i] && poss[i] <= r && ok[i])
            ++result;

    cout << result << '\n';
    return 0;
}

